# coding=utf-8
"""
Build, self-test and archive the release binaries for the current platform.
Usage: python .github/packaging/build.py [--version 1.2.3] [--qt-api pyqt6] [--arch x86] [--skip-test]
Output: dist/ScreenMagnifier-<version>-<os>-<arch>.zip | .tar.gz  (os: linux, windows, macos;
        arch: x64, arm64, x86 (32-bit), armv7, armv5, ppc64le, s390x, riscv64)
"""
from os.path import abspath, dirname, join, isdir, exists
from sys import executable, platform, exit
from subprocess import run, PIPE, STDOUT
from shutil import make_archive, rmtree
from argparse import ArgumentParser
from platform import machine
from struct import calcsize
from tempfile import mkdtemp
from os import environ

ROOT = abspath(join(dirname(__file__), '..', '..'))  # type: str  # .github/packaging -> project
DIST = join(ROOT, 'dist')  # type: str


def platformName():
    """
    :return: (tuple[str, str]) os name, architecture (x64, arm64, x86, armv7, armv5, ppc64le, s390x, riscv64 ...).
        SM_ARCH / --arch overrides the detection.
    """
    osName = 'windows' if platform == 'win32' else 'macos' if platform == 'darwin' else 'linux'  # type: str
    m = machine().lower()  # type: str
    if m in ('arm64', 'aarch64', 'armv8', 'armv8l', 'armv8b'):
        arch = 'arm64'  # type: str
    elif m in ('x86_64', 'amd64'):
        arch = 'x64'
    elif m in ('i386', 'i486', 'i586', 'i686', 'x86'):
        arch = 'x86'
    elif m.startswith('armv7') or m == 'armhf':
        arch = 'armv7'
    elif m.startswith('armv6') or m.startswith('armv5') or m == 'armel':
        arch = 'armv5'
    else:
        arch = m
    if calcsize('P') == 4:  # A 32-bit interpreter reports the 64-bit machine of its OS (AMD64 / aarch64): name the real one.
        arch = {'x64': 'x86', 'arm64': 'armv7'}.get(arch, arch)
    return osName, environ.get('SM_ARCH') or arch


def binaries():
    """
    :return: (tuple[str, str]) Paths of the built GUI and server executables.
    """
    ext = '.exe' if platform == 'win32' else ''  # type: str
    base = join(DIST, 'ScreenMagnifier.app', 'Contents', 'MacOS') if platform == 'darwin' else join(
        DIST, 'ScreenMagnifier')  # type: str
    return join(base, 'ScreenMagnifier' + ext), join(base, 'ScreenMagnifierServer' + ext)


def selfTest():
    """
    Run both frozen programs headless: a broken build must never be released.
    :return: bool
    """
    gui, server = binaries()
    env = dict(environ, QT_QPA_PLATFORM='offscreen')  # type: dict
    ok = True  # type: bool
    report = join(mkdtemp(), 'selftest.txt')  # type: str  # Windowed builds have no stdout on Windows.
    for exe, extra in ((gui, ['--selftest-report', report]), (server, [])):
        proc = run([exe, '--selftest'] + extra, stdout=PIPE, stderr=STDOUT, env=env, timeout=180)
        out = proc.stdout.decode('utf-8', 'replace')  # type: str
        if extra and exists(report):
            out += '\n' + open(report).read()
        print(out.strip()[-2000:])
        passed = proc.returncode == 0 and 'SELFTEST' in out  # type: bool
        print('[{}] {} --selftest (exit code {})'.format('ok' if passed else 'FAILED', exe, proc.returncode))
        ok = ok and passed
    return ok


def main():
    """
    :return: int
    """
    parser = ArgumentParser(description=__doc__)  # type: ArgumentParser
    parser.add_argument('--version', default=environ.get('SM_VERSION', 'dev'))
    parser.add_argument('--qt-api', default='pyqt6', choices=['pyqt6', 'pyqt5', 'pyside6', 'pyside2'])
    parser.add_argument('--arch', default='', help='architecture name of the archive (default: detected)')
    parser.add_argument('--skip-test', action='store_true')
    args = parser.parse_args()
    version = args.version.lstrip('v')  # type: str
    if args.arch:
        environ['SM_ARCH'] = args.arch
    with open(join(ROOT, 'ScreenMagnifier', '_buildinfo.py'), 'w') as f:  # Read by main.py: version + binding.
        f.write('# Generated by .github/packaging/build.py\nVERSION = {!r}\nQT_API = {!r}\n'.format(
            version, args.qt_api))
    for folder in (DIST, join(ROOT, 'build')):
        if isdir(folder):
            rmtree(folder)
    env = dict(environ, SM_QT_API=args.qt_api, SM_VERSION=version)  # type: dict
    proc = run([executable, '-m', 'PyInstaller', '--noconfirm', '--clean', '--distpath', DIST,
                '--workpath', join(ROOT, 'build'), join(ROOT, '.github', 'packaging', 'ScreenMagnifier.spec')],
               cwd=ROOT, env=env)
    if proc.returncode != 0:
        print('PyInstaller failed')
        return 1
    if not args.skip_test and not selfTest():
        return 1
    osName, arch = platformName()
    name = 'ScreenMagnifier-{}-{}-{}'.format(version, osName, arch)  # type: str
    if platform == 'darwin':  # ditto keeps the .app symlinks, permissions and signatures.
        archive = join(DIST, name + '.zip')  # type: str
        run(['ditto', '-c', '-k', '--sequesterRsrc', '--keepParent', join(DIST, 'ScreenMagnifier.app'), archive],
            check=True)
    else:
        archive = make_archive(join(DIST, name), 'zip' if platform == 'win32' else 'gztar', DIST, 'ScreenMagnifier')
    print('ARCHIVE ' + archive)
    if environ.get('GITHUB_OUTPUT'):
        with open(environ['GITHUB_OUTPUT'], 'a') as f:
            f.write('archive={}\n'.format(archive))
    return 0 if exists(archive) else 1


if __name__ == '__main__':
    exit(main())
